"""Targeted exam-centre attendance, private contacts, PIN writes and future-date gate."""
from playwright.sync_api import sync_playwright
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=b.new_page(viewport={'width':390,'height':844});page.route('**/exam-test',lambda r:r.fulfill(content_type='text/html',body='<meta name=viewport content="width=device-width,initial-scale=1"><link rel=stylesheet href=/cbse.css><link rel=stylesheet href=/cbse-mission-theme.css><main id=root></main>'));page.goto('http://127.0.0.1:8000/exam-test');errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
 page.evaluate("""async()=>{window.m=await import('./cbse-exam-centre-model.js');window.view=await import('./cbse-board-datesheet-view.js');window.draft={"classes": {"X": {"sections": {"a": {"name": "A", "subjects": {"english": {"name": "English", "code": "184"}, "science": {"name": "Science", "code": "086"}}, "students": {"one": {"name": "English Student One", "roll": "101", "subjects": {"english": true}}, "two": {"name": "English Student Two", "roll": "102", "subjects": {"english": true}}, "other": {"name": "Science Only Student", "roll": "103", "subjects": {"science": true}}}}}}}};window.contacts={'X:a:one':{guardian:'Parent One',numbers:{father:{label:'Father',phone:'9876543210'}},location:'Saved home address',mapLocation:'27.1,93.6'},'X:a:two':{guardian:'Parent Two',location:'Second home address'}};window.store={};window.clock=Date.parse('2027-02-26T04:00:00Z');window.calls=[];window.principal=false;window.start=()=>view.renderBoardDateSheet(document.querySelector('#root'),{draft,attendance:{staff:{'X:teacher':{name:'Synthetic Teacher',designation:'TGT',status:'active'}},principal,state:{},read:async scope=>{const paper=m.examCentrePaper(draft,scope);return {ok:true,paper,students:m.examCentreRoster(draft,contacts,paper),records:m.examCentreRecords(store,principal),serverDate:m.examCentreToday(clock),serverTime:clock}},save:async input=>{if(!principal&&input.pin!=='123')throw Error('Incorrect PIN');calls.push(input);store=m.applyExamCentreAttendance(store,input,{id:principal?'principal':'X:teacher',name:principal?'Principal':'Synthetic Teacher',role:principal?'principal':'staff',status:'active'},m.examCentrePaper(draft,input),clock);return {ok:true,records:m.examCentreRecords(store,principal),serverDate:m.examCentreToday(clock),serverTime:clock}}}});start();}""")
 page.locator('[name=board-standard]').select_option('X');page.locator('[data-exam-date="2027-02-26"]').get_by_role('button',name='Exam-centre attendance',exact=True).click();page.locator('.exam-centre-student').first.wait_for();assert page.locator('.exam-centre-student').count()==2;assert 'Science Only Student' not in page.locator('.exam-centre-panel').inner_text();assert page.locator('a[href="tel:9876543210"]').count()==1;assert page.locator('a[href="https://wa.me/919876543210"]').count()==1;assert page.locator('a[href*="google.com/maps/search"]').count()==2
 page.locator('[name=exam-attendance-staff]').select_option('X:teacher');one=page.locator('[data-exam-student="X:a:one"]');one.locator('[name=exam-attendance-status]').select_option('reported');one.get_by_role('button',name='Save attendance · PIN').click();page.get_by_role('dialog',name='Confirm exam attendance with PIN').wait_for();page.locator('[name=exam-attendance-pin]').fill('123');page.get_by_role('button',name='Confirm attendance',exact=True).click();page.locator('.exam-centre-reported [data-exam-student="X:a:one"]').wait_for();assert page.locator('.exam-centre-reported .exam-centre-contact').count()==0;assert '1 reported · 1 pending' in page.locator('.exam-centre-totals').inner_text();assert page.evaluate("store.students['X:a:one'].updatedBy")=='X:teacher'
 # A competing staff update is rejected until the current saved status is refreshed.
 two=page.locator('[data-exam-student="X:a:two"]');two.locator('[name=exam-attendance-status]').select_option('reported');page.evaluate("""()=>{const row={exam:'cbse',classId:'X',paperId:'X|2027-02-26|184'};store=m.applyExamCentreAttendance(store,{...row,studentKey:'X:a:two',status:'not-reported',expectedRevision:0,requestId:'other_teacher'}, {id:'other',name:'Other Teacher',role:'staff',status:'active'},m.examCentrePaper(draft,row),clock)}""");two.get_by_role('button',name='Save attendance · PIN').click();page.locator('[name=exam-attendance-pin]').fill('123');page.get_by_role('button',name='Confirm attendance',exact=True).click();page.get_by_text('Another staff member updated this student. Refresh attendance before saving.',exact=True).wait_for();assert page.evaluate("store.students['X:a:two'].status")=='not-reported';page.get_by_role('button',name='Refresh attendance',exact=True).click();page.get_by_text('Not reported at exam centre',exact=True).first.wait_for()
 for width in [320,390,768,1440]:
  page.set_viewport_size({'width':width,'height':844});assert page.evaluate('document.documentElement.scrollWidth<=innerWidth')
 # Future exams remain viewable, with all attendance writes disabled.
 page.evaluate("clock=Date.parse('2026-11-08T05:00:00Z');store={};document.querySelector('#root').replaceChildren();start()");page.locator('[name=board-standard]').select_option('X');page.locator('[data-exam-date="2027-02-26"]').get_by_role('button',name='Exam-centre attendance',exact=True).click();page.locator('.exam-centre-student').first.wait_for();assert page.locator('[name=exam-attendance-status]:enabled').count()==0;assert 'Attendance recording opens on' in page.locator('.exam-centre-panel').inner_text();assert not errors,errors;b.close()
print('PASS targeted enrolled roster, Call/WhatsApp/Maps contacts, PIN update, reported/pending groups, concurrency guard, future gate and responsive layouts')
